#include "canfd_protocol.hpp"
namespace ease_rt_x {bool CanFdProtocol::is_known_id(std::uint32_t id)const{switch(static_cast<CanFdMessageId>(id)){case CanFdMessageId::SENSOR_STATE:case CanFdMessageId::VEHICLE_STATE:case CanFdMessageId::CONTROL_COMMAND:case CanFdMessageId::HEALTH_STATUS:case CanFdMessageId::DIAGNOSTIC:case CanFdMessageId::FAULT_EVENT:case CanFdMessageId::SYSTEM_MODE:return true;default:return false;}} CanFdValidationResult CanFdProtocol::validate(const CanFdFrame&f,std::uint32_t now,std::uint32_t timeout)const{CanFdValidationResult r;r.valid_id=is_known_id(f.id);r.valid_length=f.length<=64;r.valid_sequence=f.sequence==expected_sequence_;r.fresh=(now>=f.timestamp_ms)&&(now-f.timestamp_ms<=timeout);return r;}void CanFdProtocol::accept(const CanFdFrame&f){expected_sequence_=static_cast<std::uint16_t>(f.sequence+1U);}void CanFdProtocol::reset(){expected_sequence_=0;}}
